import React, { useState, useEffect } from 'react';
import { FileUpload } from './components/FileUpload';
import { Button } from './components/Button';
import { DesignGallery } from './components/DesignGallery';
import { FileData, GeneratedDesign } from './types';
import { STYLE_DIRECTIONS } from './constants';
import { generateDesignForStyle } from './services/geminiService';
import { Palette, Key, ShieldCheck, Info } from 'lucide-react';

const App: React.FC = () => {
  // State
  const [apiKeySelected, setApiKeySelected] = useState<boolean>(false);
  const [targetImage, setTargetImage] = useState<FileData[]>([]);
  const [brandImages, setBrandImages] = useState<FileData[]>([]);
  const [userPrompt, setUserPrompt] = useState<string>('');

  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [designs, setDesigns] = useState<GeneratedDesign[]>([]);

  // Check for API Key on mount
  useEffect(() => {
    checkApiKey();
  }, []);

  const checkApiKey = async () => {
    if (window.aistudio && window.aistudio.hasSelectedApiKey) {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      setApiKeySelected(hasKey);
    }
  };

  const handleSelectKey = async () => {
    if (window.aistudio && window.aistudio.openSelectKey) {
      await window.aistudio.openSelectKey();
      // Assume success as per race condition instructions
      setApiKeySelected(true);
    }
  };

  const handleGenerate = async () => {
    if (!apiKeySelected) {
      await handleSelectKey();
    }
    if (targetImage.length === 0) return;

    setIsGenerating(true);

    // Initialize placeholders
    const initialDesigns: GeneratedDesign[] = STYLE_DIRECTIONS.map(style => ({
      id: Math.random().toString(),
      styleId: style.id,
      styleTitle: style.title,
      imageUrl: '',
      status: 'pending'
    }));
    setDesigns(initialDesigns);

    // Process sequentially to show progress and avoid rate limits
    for (let i = 0; i < STYLE_DIRECTIONS.length; i++) {
      const style = STYLE_DIRECTIONS[i];

      // Update status to generating
      setDesigns(prev => prev.map(d => 
        d.styleId === style.id ? { ...d, status: 'generating' } : d
      ));

      try {
        const generatedImageUrl = await generateDesignForStyle(
          process.env.API_KEY || '',
          style,
          targetImage[0],
          brandImages,
          userPrompt
        );

        setDesigns(prev => prev.map(d => 
          d.styleId === style.id ? { ...d, status: 'completed', imageUrl: generatedImageUrl } : d
        ));
      } catch (error) {
        console.error(error);
        setDesigns(prev => prev.map(d => 
          d.styleId === style.id ? { ...d, status: 'failed' } : d
        ));
      }
    }

    setIsGenerating(false);
  };

  return (
    <div className="min-h-screen bg-gray-50 text-charcoal font-sans selection:bg-gold-200 selection:text-charcoal">

      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-gold-500 p-2 rounded-sm text-white">
              <Palette size={24} />
            </div>
            <div>
              <h1 className="font-serif text-2xl font-bold tracking-tight text-charcoal">LUMINA</h1>
              <p className="text-[10px] uppercase tracking-[0.2em] text-gold-600">Hospitality Design AI</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
             {!apiKeySelected && (
               <Button variant="text" onClick={handleSelectKey} className="text-xs">
                 <Key size={14} className="mr-1" /> Connect API Key
               </Button>
             )}
             {apiKeySelected && (
               <div className="flex items-center gap-2 text-green-700 text-xs font-semibold px-3 py-1 bg-green-50 rounded-full border border-green-100">
                 <ShieldCheck size={14} />
                 API Connected
               </div>
             )}
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main>
        {/* Hero / Upload Section */}
        <section className="bg-white pb-16 pt-12 border-b border-gray-200">
          <div className="max-w-4xl mx-auto px-6">

            <div className="text-center mb-12">
              <h2 className="font-serif text-4xl lg:text-5xl text-charcoal mb-4">Reimagine Your Corridor</h2>
              <p className="text-gray-500 text-lg font-light max-w-2xl mx-auto">
                Transform existing spaces into 5 distinct luxury concepts using advanced architectural AI.
                Simply upload your target corridor and brand references.
              </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-10">
              <FileUpload 
                label="1. Target Corridor"
                subLabel="(Perspective Reference)"
                files={targetImage}
                onFilesChange={setTargetImage}
                maxFiles={1}
                className="h-full"
              />
              <FileUpload 
                label="2. Brand DNA"
                subLabel="(Style References - Up to 5)"
                multiple
                maxFiles={5}
                files={brandImages}
                onFilesChange={setBrandImages}
                className="h-full"
              />
            </div>

            <div className="mb-10">
              <label className="block text-sm font-bold text-charcoal uppercase tracking-wider mb-2">
                3. Design Nuance (Optional)
              </label>
              <textarea 
                className="w-full border border-gray-300 rounded-lg p-4 focus:ring-2 focus:ring-gold-400 focus:border-transparent outline-none transition-all resize-none text-gray-700 placeholder-gray-400 bg-gray-50"
                rows={3}
                placeholder='e.g., "Make the lighting warmer", "Add more brass details", "Use a darker carpet"...'
                value={userPrompt}
                onChange={(e) => setUserPrompt(e.target.value)}
              />
              <div className="flex items-center gap-2 mt-2 text-xs text-gray-400">
                <Info size={14} />
                <span>The AI will intelligently apply this nuance to all 5 style directions.</span>
              </div>
            </div>

            <div className="flex justify-center">
              <Button 
                onClick={handleGenerate} 
                disabled={targetImage.length === 0 || isGenerating}
                isLoading={isGenerating}
                className="w-full md:w-auto min-w-[300px] text-lg py-4 shadow-xl hover:shadow-2xl hover:-translate-y-1"
              >
                {targetImage.length === 0 ? 'Upload Target Image to Begin' : 'Generate 5 Design Concepts'}
              </Button>
            </div>

             {!apiKeySelected && (
                <p className="text-center text-xs text-red-500 mt-4">
                  * Note: This tool requires a paid API key for high-quality architectural rendering.
                </p>
             )}

          </div>
        </section>

        {/* Results Gallery */}
        <DesignGallery designs={designs} />

      </main>

      {/* Footer */}
      <footer className="bg-charcoal text-white py-12 border-t border-gray-800">
        <div className="max-w-7xl mx-auto px-6 flex flex-col md:flex-row justify-between items-center opacity-60">
           <div className="flex items-center gap-2 mb-4 md:mb-0">
            <Palette size={20} className="text-gold-500" />
            <span className="font-serif font-bold text-lg tracking-wide">LUMINA</span>
           </div>
           <p className="text-sm font-sans">© 2024 Lumina AI Design. Architectural Visualization Engine.</p>
        </div>
      </footer>
    </div>
  );
};

export default App;

